import fs from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
const root=process.env.H_EARTH_REPO_ROOT||'/workspace/scratch/50f4948b4973/repo';
const imp=p=>import(pathToFileURL(root+'/'+p));
const hash=s=>createHash('sha256').update(s).digest('hex');
const start=performance.now(),canonicalBytes=fs.readFileSync(root+'/showroom/globe/h-earth/render/assets/h-earth-canonical-base-world.v1.json.gz');
const pkg=JSON.parse(gunzipSync(canonicalBytes)).canonical;
const before=hash(JSON.stringify(pkg));
const bridge=await imp('showroom/globe/h-earth/functional-landscape/geological-runtime-bridge.v1.js');
const {unprojectPlanetVertex}=await imp('h-earth-3d/terrain/h-earth.geological-formation-successor.v1.mjs');
const {buildVegetationVisibleSurface}=await imp('showroom/globe/h-earth/render/vegetation-visible-surface.v1.js');
const {buildHEarthGlobalGroundCover,transformHEarthGroundCoverRoot}=await imp('showroom/globe/h-earth/render/landscape-groundcover.global-v1.js');
const {createNearbyFineGrassCache}=await imp('showroom/globe/h-earth/render/woodland-fine-grass.v1.js');
const model=bridge.constructGeologicalRuntimeBridge(pkg);
console.log('ACTUAL_MODEL_READY',Math.round(performance.now()-start));
const visible=buildVegetationVisibleSurface(pkg,{geology:model});
// Independent diagnostic index: direct barycentric intersection of the actual
// projected indexed upload geometry, not the product surface sampler.
function rays(parts){
 const bins=new Map(),size=8;let triangles=0;
 for(const {mesh} of parts){const p=mesh.positions,ind=mesh.indices;
  for(let k=0;k<ind.length;k+=3){
   const a=ind[k]*3,b=ind[k+1]*3,c=ind[k+2]*3;
   const det=(p[b+2]-p[c+2])*(p[a]-p[c])+(p[c]-p[b])*(p[a+2]-p[c+2]);
   if(Math.abs(det)<1e-12)continue;
   const xmin=Math.min(p[a],p[b],p[c]),xmax=Math.max(p[a],p[b],p[c]),zmin=Math.min(p[a+2],p[b+2],p[c+2]),zmax=Math.max(p[a+2],p[b+2],p[c+2]);
   const t={p,a,b,c,det};triangles++;
   for(let iz=Math.floor(zmin/size);iz<=Math.floor(zmax/size);iz++)for(let ix=Math.floor(xmin/size);ix<=Math.floor(xmax/size);ix++){
    const key=ix+':'+iz;if(!bins.has(key))bins.set(key,[]);bins.get(key).push(t);
   }
  }
 }
 return {triangles,at(x,z){let top=null;
  for(const {p,a,b,c,det} of bins.get(Math.floor(x/size)+':'+Math.floor(z/size))??[]){
   const u=((p[b+2]-p[c+2])*(x-p[c])+(p[c]-p[b])*(z-p[c+2]))/det,v=((p[c+2]-p[a+2])*(x-p[c])+(p[a]-p[c])*(z-p[c+2]))/det,w=1-u-v;
   if(Math.min(u,v,w)<-1e-7)continue;const y=u*p[a+1]+v*p[b+1]+w*p[c+1];if(top===null||y>top)top=y;
  }return top;
 }};
}
const exterior=rays(model.meshes.filter(p=>['ERODED_TERRAIN','MOUNTAIN_OVERBURDEN'].includes(p.role)));
const water=rays(model.meshes.filter(p=>['FRESHWATER_RIVER','OASIS_WATER'].includes(p.role)));
const retired=new Set(model.retirement.triangleOffsets),retainedTerrainIndices=[];
for(const span of pkg.primitiveSpans.filter(s=>s.role==='TERRAIN'))for(let i=span.indexStart;i<span.indexStart+span.indexCount;i+=3)if(!retired.has(i))retainedTerrainIndices.push(...pkg.buffers.indices.slice(i,i+3));
const retainedBase=rays([{mesh:{positions:Float32Array.from(pkg.buffers.positions),indices:Uint32Array.from(retainedTerrainIndices)}}]);
const p=model.meshes.filter(p=>['ERODED_TERRAIN','MOUNTAIN_OVERBURDEN'].includes(p.role)).flatMap(p=>Array.from(p.mesh.positions));
const box=[Infinity,Infinity,-Infinity,-Infinity];for(let i=0;i<p.length;i+=3){box[0]=Math.min(box[0],p[i]);box[1]=Math.min(box[1],p[i+2]);box[2]=Math.max(box[2],p[i]);box[3]=Math.max(box[3],p[i+2]);}
const inBox=(x,z)=>x>=box[0]&&x<=box[2]&&z>=box[1]&&z<=box[3];
// Construct complete tiles around the geology bounds, including root collars
// crossing their centers' tile edges. This preserves per-tile ecology ranking.
const tileBox=[Math.floor((box[0]-2)/32)*32,Math.floor((box[1]-2)/32)*32,Math.ceil((box[2]+2)/32)*32,Math.ceil((box[3]+2)/32)*32];
const scoped={...visible,sample:(x,z)=>x>=tileBox[0]-2&&x<=tileBox[2]+2&&z>=tileBox[1]-2&&z<=tileBox[3]+2?visible.sample(x,z):null};
// The global ecological cap cannot affect selection: count every eligible tile
// in all three unchanged ecological windows, then bound each by its 24 records.
const ecoWindows=[[-213,-296,-69,-156],[-90,-168,90,-24],[-127,-394,37,-258]];
let eligibleEcoTiles=0;for(let iz=0;iz<27;iz++)for(let ix=0;ix<24;ix++){const x=-384+ix*32,z=-736+iz*32;if(ecoWindows.some(w=>x<=w[2]&&x+32>=w[0]&&z<=w[3]&&z+32>=w[1]))eligibleEcoTiles++;}
if(eligibleEcoTiles*24>=4301)throw Error('GLOBAL_ECOLOGY_CAP_SELECTION_INDEPENDENCE_UNPROVEN');
const cover=await buildHEarthGlobalGroundCover(pkg,{visibleSurface:scoped,compositionEnabled:true});
console.log('ACTUAL_GLOBAL_GEOLOGY_READY',cover.receipt.instanceCount,Math.round(performance.now()-start));
function metrics(points){
 const output={roots:points.length,rootsWithExteriorIntersection:0,retainedVisibleBaseBoundaryRoots:0,missingVisibleSupport:0,floatingOver1cm:0,buriedOver1cm:0,waterOverlap:0,insideCavernVoid:0,maxAbsoluteContactError:0,maxFloat:0,maxBurial:0,boundaryExamples:[],failures:[]};
 for(const q of points){const exteriorY=exterior.at(q.x,q.z),w=water.at(q.x,q.z);let y=exteriorY;
  if(y===null){y=retainedBase.at(q.x,q.z);if(y===null){output.missingVisibleSupport++;if(output.failures.length<10)output.failures.push({...q,reason:'NO_VISIBLE_SUPPORT'});continue;}
   output.retainedVisibleBaseBoundaryRoots++;if(output.boundaryExamples.length<10)output.boundaryExamples.push({...q,retainedBaseY:y,error:q.y-y,reason:'PROJECTED_GEOLOGY_BOUNDS_BOX_EXCEEDS_ACTUAL_CURVED_EXTERIOR_FOOTPRINT'});
  }else output.rootsWithExteriorIntersection++;
  const error=q.y-y;output.maxAbsoluteContactError=Math.max(output.maxAbsoluteContactError,Math.abs(error));output.maxFloat=Math.max(output.maxFloat,error);output.maxBurial=Math.max(output.maxBurial,-error);
  if(error>.01)output.floatingOver1cm++;if(error<-.01)output.buriedOver1cm++;
  if(w!==null&&q.y<=w+.009)output.waterOverlap++;
  const a=unprojectPlanetVertex(q.x,q.y,q.z);if(model.formation.insideVoid(a.x,a.y,a.z))output.insideCavernVoid++;
  if((Math.abs(error)>.01||(w!==null&&q.y<=w+.009))&&output.failures.length<10)output.failures.push({...q,exteriorY:y,waterY:w,error});
 }return output;
}
const globalPoints=[];
for(let i=0;i<cover.records.length;i+=20){const r=cover.records.subarray(i,i+20);
 for(let collar=0;collar<12;collar++){const xz=transformHEarthGroundCoverRoot(cover.template,collar,r[12],r[13],r[14],r[15]);if(inBox(xz.x,xz.z))globalPoints.push({...xz,y:r[collar],record:i/20,collar});}
}
const global=metrics(globalPoints),nearbyCache=createNearbyFineGrassCache(pkg,{visibleSurface:visible});
const nearStart=performance.now(),nearby=await nearbyCache.update({x:40,z:-300},{coreRadiusMeters:8,outerRadiusMeters:12});
const nearPoints=nearby.tiles.flatMap(t=>t.roots),near=metrics(nearPoints);
const after=hash(JSON.stringify(pkg));
const report={schema:'H_EARTH_ACTUAL_GEOLOGY_ROOT_CONTACT_PROOF_v1',sourceBinarySha256:hash(canonicalBytes),sourceWorldBeforeSha256:before,sourceWorldAfterSha256:after,sourceWorldUnchanged:before===after,scope:'ALL_GLOBAL_LATTICE_AND_ECOLOGY_COLLARS_WITHIN_ACTUAL_PROJECTED_GEOLOGY_BOUNDS; COMPLETE_INTERSECTING_TILES_PLUS_ROOT_APRON; NEARBY_INITIAL_8M_CORE_12M_OUTER',geometry:'ACTUAL_PROJECTED_FLOAT32_INDEXED_EXTERIOR_AND_WATER_MESHES',regionBox:box,generationTileBox:tileBox,eligibleEcologyTilesWorldWide:eligibleEcoTiles,globalEcologyUpperBound:eligibleEcoTiles*24,globalEcologyCap:4301,independentExteriorTriangles:exterior.triangles,independentWaterTriangles:water.triangles,global:{...global,generatedRegionalAndApronInstances:cover.receipt.instanceCount,buildReceipt:cover.receipt},nearby:{...near,buildMilliseconds:performance.now()-nearStart,buildReceipt:nearby.receipt},totalMilliseconds:performance.now()-start};
report.passed=report.sourceWorldUnchanged&&[global,near].every(r=>r.roots>0&&r.missingVisibleSupport===0&&r.floatingOver1cm===0&&r.buriedOver1cm===0&&r.waterOverlap===0&&r.insideCavernVoid===0);
fs.writeFileSync('/tmp/h-earth-investigation/repaired-actual-root-proof.json',JSON.stringify(report,null,2));
console.log(JSON.stringify(report,null,2));
if(!report.passed)process.exitCode=1;
